script:
(function () {
  function findShadowRoot() {
    var all = document.querySelectorAll("*");
    for (var i = 0; i < all.length; i++) {
      var el = all[i];
      if (el.tagName && el.tagName.toLowerCase().indexOf("custom-block") === 0 && el.shadowRoot) {
        if (el.shadowRoot.getElementById("alaa-headline")) return el.shadowRoot;
      }
    }
    return null;
  }

  function fmtSar(n) {
    return Math.round(n || 0).toLocaleString("ar-SA");
  }

  function render(root, data) {
    var h = root.getElementById("alaa-headline");
    var p = root.getElementById("alaa-body");
    var ov = root.getElementById("kpi-overdue-value");
    var ovt = root.getElementById("kpi-overdue-trend");

    if (data.error) {
      if (h) h.textContent = "تعذّر تحميل تحليل ألاء الآن";
      if (p) p.textContent = data.error;
      if (ov) ov.textContent = "—";
      if (ovt) ovt.textContent = "";
      return;
    }

    if (h) h.textContent = data.headline || "";
    if (p) p.textContent = data.body || "";

    var kpis = data.kpis || {};
    if (ov) ov.innerHTML = fmtSar(kpis.overdueTotal) + "<small>ر.س</small>";
    if (ovt) {
      var top = (kpis.topOverdue || [])[0];
      ovt.textContent = top
        ? (top.customer + " — " + fmtSar(top.amount) + " ر.س")
        : (kpis.overdueCustomers ? kpis.overdueCustomers + " عميل" : "مفيش متأخرات");
    }
  }

  function esc(s) {
    return (window.frappe && frappe.utils && frappe.utils.escape_html) ? frappe.utils.escape_html(s || "") : (s || "");
  }

  function renderFeed(root, data) {
    var table = root.getElementById("invoices-table");
    if (table) {
      var rows = "<tr><th>العميل</th><th class=\"num\">القيمة</th><th></th></tr>";
      var invoices = data.invoices || [];
      if (!invoices.length) {
        rows += "<tr><td colspan=\"3\" style=\"text-align:center;color:var(--h-steel)\">مفيش فواتير لسه</td></tr>";
      } else {
        invoices.forEach(function (inv) {
          var pillClass = inv.paid ? "green" : "orange";
          var pillText = inv.paid ? "مدفوعة" : "غير مدفوعة";
          rows += "<tr><td><a href=\"" + inv.url + "\" style=\"color:inherit;text-decoration:none\">" + esc(inv.customer) + "</a></td>" +
            "<td class=\"num\">" + fmtSar(inv.grand_total) + "</td>" +
            "<td><span class=\"indicator-pill " + pillClass + "\" style=\"padding:2px 9px;font-size:.7rem\">" + pillText + "</span></td></tr>";
        });
      }
      table.innerHTML = rows;
    }

    var feed = root.getElementById("activity-feed");
    if (feed) {
      var activities = data.activities || [];
      if (!activities.length) {
        feed.innerHTML = "<div class=\"act-row\"><span class=\"act-txt\">مفيش نشاط لسه</span></div>";
      } else {
        feed.innerHTML = activities.map(function (a) {
          return "<a href=\"" + a.url + "\" class=\"act-row\" style=\"display:flex;align-items:center;color:inherit;text-decoration:none\">" +
            "<span class=\"act-dot\" style=\"background:var(" + (a.color || "--h-blue") + ")\"></span>" +
            "<span class=\"act-txt\">" + esc(a.label) + "</span>" +
            "<span class=\"act-time\">" + esc(a.time_ago) + "</span></a>";
        }).join("");
      }
    }
  }

  var root = findShadowRoot();
  if (!root || !window.frappe) return;

  frappe.call({ method: "alaa_widget.api.alaa_insight.get_daily_insight" })
    .then(function (r) { render(root, r.message || {}); })
    .catch(function () { render(root, { error: "تعذّر الاتصال بألاء" }); });

  // بلاغ المالك (٣٠ أغسطس): "ايه فايدتهم وانا مش قادر اضغط عليهم" —
  // جدول الفواتير وقائمة الأنشطة كانا نصًا ثابتًا بلا روابط. دلوقتي
  // بيانات حقيقية (Sales Invoice/Journal Entry/Payment Entry الفعلية)
  // وكل صف بيفتح المستند نفسه في فرابي.

  function fmtMillions(n) {
    return (Math.abs(n) / 1e6).toFixed(2);
  }

  function renderKpis(root, data) {
    var cashVal = root.getElementById("kpi-cash-value");
    var cashTrend = root.getElementById("kpi-cash-trend");
    if (cashVal && cashTrend) {
      if (data.net_cash) {
        cashVal.innerHTML = fmtMillions(data.net_cash.value) + "<small>م ر.س</small>";
        var ct = data.net_cash.trend_pct;
        cashTrend.className = "k-trend " + (ct >= 0 ? "up" : "down");
        cashTrend.textContent = (ct >= 0 ? "▲ " : "▼ ") + Math.abs(ct).toFixed(1) + "٪ عن الأسبوع الماضي";
      } else {
        cashVal.textContent = "—";
        cashTrend.textContent = "لسه مفيش حركة بنكية مسجّلة";
      }
    }

    var devVal = root.getElementById("kpi-deviation-value");
    var devTrend = root.getElementById("kpi-deviation-trend");
    if (devVal && devTrend) {
      if (data.cost_deviation) {
        var dv = data.cost_deviation.value;
        devVal.innerHTML = (dv >= 0 ? "+" : "") + dv.toFixed(1) + "<small>٪</small>";
        devTrend.className = "k-trend " + (dv > 5 ? "warn" : "up");
        devTrend.textContent = data.cost_deviation.worst_order + " وحده سبب " + Math.round(data.cost_deviation.worst_share_pct) + "٪ منه";
      } else {
        devVal.textContent = "—";
        devTrend.textContent = "لا أوامر تشغيل هالشهر";
      }
    }

    var marVal = root.getElementById("kpi-margin-value");
    var marTrend = root.getElementById("kpi-margin-trend");
    if (marVal && marTrend) {
      if (data.margin) {
        var mv = data.margin.value;
        marVal.innerHTML = mv.toFixed(1) + "<small>٪</small>";
        marTrend.className = "k-trend " + (mv >= 0 ? "up" : "down");
        marTrend.textContent = (mv >= 0 ? "▲" : "▼") + " هامش الشهر الحالي";
      } else {
        marVal.textContent = "—";
        marTrend.textContent = "بيانات الشهر غير كافية بعد";
      }
    }
  }

  frappe.call({ method: "horizon_tab_theme.api.dashboard_feed.get_dashboard_feed" })
    .then(function (r) { renderFeed(root, r.message || {}); })
    .catch(function () { renderFeed(root, {}); });

  frappe.call({ method: "horizon_tab_theme.api.dashboard_feed.get_kpi_metrics" })
    .then(function (r) { renderKpis(root, r.message || {}); })
    .catch(function () { renderKpis(root, {}); });
})();

style:
:root{
  --h-navy-950:#101A2B;
  --h-navy-900:#16233A;
  --h-navy:#1D2D44;
  --h-navy-700:#2A3D5C;
  --h-navy-500:#3D5170;
  --h-navy-300:#7C8CA6;
  --h-steel:#8FA8CC;
  --h-steel-soft:rgba(143,168,204,.14);
  --h-blue:#5083BC;
  --h-blue-soft:rgba(80,131,188,.10);
  --h-amber:#B8860B;
  --h-amber-soft:rgba(184,134,11,.12);
  --h-green:#4E7A5C;
  --h-green-soft:rgba(78,122,92,.12);
  --h-red:#B04A3F;
  --h-red-soft:rgba(176,74,63,.10);

  --h-ink:#1A1717;
  --h-muted:#4A5361;
  --h-faint:#69727F;
  --h-paper:#F7F8F6;
  --h-card:#FFFFFF;
  --h-line:#E3E5E0;
  --h-sand:#EDEEEA;

  --h-on-dark:#EEF2F9;
  --h-on-dark-2:#B6C2DA;
  --h-on-dark-3:#8B9AB8;

  --h-r-lg:16px;
  --h-r-md:10px;
  --h-r-sm:7px;
  --h-shadow-1:0 1px 2px rgba(29,45,68,.05),0 6px 16px -8px rgba(29,45,68,.12);
  --h-shadow-2:0 4px 10px rgba(29,45,68,.08),0 20px 44px -16px rgba(29,45,68,.22);
  --h-font:'Tajawal','Inter',-apple-system,BlinkMacSystemFont,'Segoe UI',sans-serif;
  --h-mono:'JetBrains Mono','SFMono-Regular',Consolas,monospace;
}

:root{
  /* 8px base grid — bento cells and gaps are all multiples of this,
     per the sizing convention in every 2026 bento guide reviewed */
  --h-space-1: 4px; --h-space-2: 8px; --h-space-3: 12px; --h-space-4: 16px;
  --h-space-6: 24px; --h-space-8: 32px;
  --h-bento-radius: 18px;
  --h-canvas: #F4F6F5; /* calmer than pure white — Mercury/Ramp's dashboard
                           backdrop is never stark white behind the cards,
                           it's what makes white CARDS read as elevated */
}

.dash-canvas{ background: var(--h-canvas); padding: var(--h-space-6); min-height: 100%; }

.dash-head{ display:flex; justify-content:space-between; align-items:flex-end; margin-bottom: var(--h-space-6); flex-wrap:wrap; gap:12px; }
.dash-head h1{ font-size:1.5rem; font-weight:900; color:var(--h-navy-900); margin:0; }
.dash-head .sub{ font-size:.85rem; color:var(--h-muted); font-weight:600; margin-top:4px; }

/* ── the grid itself ──────────────────────────────────────────────────── */
.bento-grid{
  display:grid;
  grid-template-columns: repeat(4, 1fr);
  grid-auto-rows: 118px;
  gap: var(--h-space-4);
}
@media (max-width: 900px){ .bento-grid{ grid-template-columns: repeat(2,1fr); } }
@media (max-width: 560px){ .bento-grid{ grid-template-columns: 1fr; grid-auto-rows: auto; } }

.bento-card{
  background:#fff; border:1px solid var(--h-line); border-radius: var(--h-bento-radius);
  padding: var(--h-space-4) var(--h-space-4);
  box-shadow: 0 1px 2px rgba(29,45,68,.04);
  display:flex; flex-direction:column;
  transition: box-shadow .2s, transform .2s;
  overflow:hidden; position:relative;
}
.bento-card:hover{ box-shadow: 0 8px 24px -10px rgba(29,45,68,.16); }
.span-2x2{ grid-column: span 2; grid-row: span 2; }
.span-2x1{ grid-column: span 2; }
.span-1x2{ grid-row: span 2; }
@media (max-width: 560px){ .span-2x2,.span-2x1,.span-1x2{ grid-column: span 1 !important; grid-row: auto !important; } }

/* ── the AI anchor card — navy, largest cell, always top-start ─────────── */
.bento-ai{
  background: linear-gradient(155deg, var(--h-navy-700), var(--h-navy-950));
  color:#fff; border:none;
  box-shadow: 0 20px 50px -20px rgba(16,26,43,.5);
}
.bento-ai::before{
  content:""; position:absolute; inset:0;
  background: radial-gradient(60% 50% at 100% 0%, rgba(143,168,204,.28), transparent 70%);
}
.bento-ai .ai-tag{ position:relative; display:inline-flex; align-items:center; gap:7px;
  font-size:.72rem; font-weight:800; color:var(--h-steel); margin-bottom:14px; }
.bento-ai .ai-tag .dot{ width:6px;height:6px;border-radius:50%; background:var(--h-steel); animation:aiPulse 2s infinite; }
@keyframes aiPulse{ 0%,100%{opacity:.4} 50%{opacity:1} }
.bento-ai h3{ position:relative; font-size:1.15rem; font-weight:800; line-height:1.6; margin:0 0 10px; color:#fff; max-width:34ch; }
.bento-ai p{ position:relative; font-size:.86rem; color:rgba(255,255,255,.72); font-weight:600; line-height:1.9; margin:0 0 16px; max-width:38ch; }
.bento-ai .ai-actions{ position:relative; display:flex; gap:8px; margin-top:auto; }
.bento-ai .ai-btn{ background:#fff; color:var(--h-navy); font-weight:800; font-size:.8rem;
  padding:8px 16px; border-radius:99px; border:none; cursor:pointer; }
.bento-ai .ai-btn.ghost{ background:rgba(255,255,255,.12); color:#fff; border:1px solid rgba(255,255,255,.25); }

/* ── KPI cards — one number, tabular, restrained ─────────────────────── */
.bento-kpi .k-label{ font-size:.74rem; font-weight:800; color:var(--h-faint); text-transform:uppercase; letter-spacing:.02em; }
.bento-kpi .k-value{ font-size:1.7rem; font-weight:900; color:var(--h-navy-900); font-variant-numeric:tabular-nums;
  margin-top:auto; line-height:1.1; }
.bento-kpi .k-value small{ font-size:.5em; font-weight:800; color:var(--h-faint); margin-inline-start:4px; }
.bento-kpi .k-trend{ font-size:.76rem; font-weight:800; margin-top:6px; display:flex; align-items:center; gap:4px; }
.bento-kpi .k-trend.up{ color:var(--h-blue); }
.bento-kpi .k-trend.warn{ color:var(--h-amber); }
.bento-kpi .k-trend.down{ color:var(--h-red); }

/* ── mini sparkline card ─────────────────────────────────────────────── */
.bento-chart .k-label{ font-size:.74rem; font-weight:800; color:var(--h-faint); text-transform:uppercase; margin-bottom:8px; }
.spark{ display:flex; align-items:flex-end; gap:4px; flex:1; }
.spark b{ flex:1; background:var(--h-line); border-radius:3px 3px 1px 1px; transform-origin:bottom; }
.spark b.hi{ background:var(--h-navy); }

/* ── activity list card ──────────────────────────────────────────────── */
.bento-activity .act-row{ display:flex; align-items:center; gap:10px; padding:7px 0; border-bottom:1px solid var(--h-line); font-size:.82rem; }
.bento-activity .act-row:last-child{ border-bottom:none; }
.bento-activity .act-dot{ width:7px;height:7px;border-radius:50%; flex:none; }
.bento-activity .act-txt{ flex:1; color:var(--h-ink); font-weight:600; overflow:hidden; text-overflow:ellipsis; white-space:nowrap; }
.bento-activity .act-time{ color:var(--h-faint); font-size:.74rem; font-weight:700; flex:none; }

/* ── dense table card (accountant density, per research: power users want
   density; the dashboard around it stays calm — density lives INSIDE one
   card, not across the whole screen) ─────────────────────────────────── */
.bento-table table{ width:100%; border-collapse:collapse; font-size:.82rem; }
.bento-table th{ text-align:start; font-size:.7rem; font-weight:800; color:var(--h-faint); text-transform:uppercase;
  padding:0 0 8px; border-bottom:1px solid var(--h-line); }
.bento-table th.num, .bento-table td.num{ text-align:end; font-variant-numeric:tabular-nums; }
.bento-table td{ padding:8px 0; border-bottom:1px solid var(--h-line); color:var(--h-ink); font-weight:600; }
.bento-table tr:last-child td{ border-bottom:none; }

/* ── empty state — onboarding, not a blank box ───────────────────────── */
.bento-empty{ display:flex; flex-direction:column; align-items:center; justify-content:center; text-align:center;
  flex:1; gap:8px; padding:10px; }
.bento-empty .e-ic{ width:38px;height:38px;border-radius:10px; background:var(--h-sand); color:var(--h-navy-300);
  display:grid; place-items:center; margin-bottom:4px; }
.bento-empty .e-t{ font-size:.82rem; font-weight:800; color:var(--h-navy-900); }
.bento-empty .e-d{ font-size:.74rem; color:var(--h-faint); font-weight:600; max-width:20ch; }
.bento-empty a{ margin-top:6px; }

@media (prefers-color-scheme: dark){
  .dash-canvas{ background: var(--h-canvas) !important; }
  .bento-card{ background-color:#fff !important; }
  .bento-ai{ background: linear-gradient(155deg, var(--h-navy-700), var(--h-navy-950)) !important; }
}
